export const MINI: Partial<Record<IkonNavn, IkonPar>> = {
  ...M,
  'utstyr': M['ski'],
}

export const ALIAS: Readonly<Record<string, BasisNavn>> = {'utstyr': 'ski', 'styrketrening': 'live-styrke', 'peak': 'favoritt'}
export const IKON_NAVN = Object.keys(IKONER).sort() as IkonNavn[]

export interface IkonProps {
  navn: IkonNavn
  /** strek (tynn) i menyer, topplinje, knapper, innstillinger; fyll for markeringer i plan/dagbok/graf. */
  variant?: IkonVariant
  storrelse?: IkonStorrelse
  /** auto = mini ved 14 px der den finnes. standard/mini tvinger. */
  optisk?: IkonOptisk
  className?: string
  style?: CSSProperties
  /** Settes bare når ikonet står ALENE og bærer mening (ellers er det dekor for skjermleseren). */
  tittel?: string
}

export function ikonStier(navn: IkonNavn, variant: IkonVariant = 'strek', storrelse: number = 18, optisk: IkonOptisk = 'auto'): { stier: readonly string[]; mini: boolean } {
  const liten = optisk === 'mini' || (optisk === 'auto' && storrelse <= 14)
  const m = liten ? MINI[navn] : undefined
  const par = m ?? IKONER[navn]
  return { stier: par[variant], mini: !!m }
}

export function Ikon({ navn, variant = 'strek', storrelse = 18, optisk = 'auto', className, style, tittel }: IkonProps) {
  const { stier, mini } = ikonStier(navn, variant, storrelse, optisk)
  const tegn = variant === 'strek'
    ? { fill: 'none', stroke: 'currentColor', strokeWidth: 1.7, strokeLinecap: 'round' as const, strokeLinejoin: 'round' as const }
    : { fill: 'currentColor', fillRule: 'nonzero' as const }
  return (
    <svg viewBox="0 0 24 24" width={storrelse} height={storrelse} {...tegn}
      aria-hidden={tittel ? undefined : true} role={tittel ? 'img' : undefined}
      className={className} data-ikon={navn} data-variant={variant} data-optisk={mini ? 'mini' : 'standard'}
      style={{ display: 'inline-block', flexShrink: 0, verticalAlign: 'middle', ...style }}>
      {tittel && <title>{tittel}</title>}
      {stier.map((d, i) => <path key={i} d={d} />)}
    </svg>
  )
}
